 DECLARE   v_today           DATE := CURRENT_DATE;   v_total_prj       INT  := 0;   v_live_prj        INT  := 0;   v_delayed_prj     INT  := 0;   v_progress_sum    NUMERIC := 0;   v_ms_completed    INT := 0;   v_ms_in_progress  INT := 0;   v_ms_not_started  INT := 0;   v_ms_delayed      INT := 0;   v_t_total         INT := 0;   v_t_completed     INT := 0;   v_t_in_progress   INT := 0;   v_t_under_review  INT := 0;   v_t_not_started   INT := 0;   v_t_overdue       INT := 0;   v_earliest_start  DATE;   v_latest_end      DATE;   v_planned_pct     NUMERIC := 0;   v_overall_pct     NUMERIC := 0;   v_delayed_ms      jsonb;   v_upcoming_ms     jsonb;   v_hp_tasks        jsonb;   rec               RECORD;   v_prj_t_total     INT;   v_prj_t_done      INT;   v_p_completed     INT := 0;   v_p_in_progress   INT := 0;   v_p_not_started   INT := 0;   v_p_delayed       INT := 0;   v_may_delay_prj   INT := 0;   v_prj_total_weight      NUMERIC;   v_prj_completed_weight  NUMERIC;   v_prj_progress          NUMERIC;   v_active_prj            INT := 0; BEGIN   SELECT MIN(st_dt), MAX(end_dt) INTO v_earliest_start, v_latest_end   FROM project_live_master;    FOR rec IN SELECT prj_id, prj_sts, end_dt FROM project_live_master LOOP     v_total_prj := v_total_prj + 1;     IF rec.prj_sts = 'LIVE' THEN v_live_prj := v_live_prj + 1; END IF;      IF rec.prj_sts IN ('LIVE', 'CLOSED') THEN       v_active_prj := v_active_prj + 1;       IF rec.prj_sts = 'CLOSED' THEN         v_prj_progress := 100.0;       ELSE         SELECT           COALESCE(SUM(             CASE               WHEN t.wrk_days IS NOT NULL AND t.wrk_days > 0 THEN t.wrk_days               WHEN t.no_of_days IS NOT NULL AND t.no_of_days > 0 THEN t.no_of_days               ELSE 1.0             END           ), 0),           COALESCE(SUM(             CASE               WHEN tsm.status_nm = 'Completed' THEN 100.0               WHEN tsm.status_nm = 'WIP' AND t.sub_status = 'Under Review' THEN 80.0               WHEN tsm.status_nm = 'WIP' AND t.sub_status = 'Rework' THEN 20.0               WHEN tsm.status_nm = 'WIP' THEN 50.0               ELSE 0.0             END / 100.0 *             CASE               WHEN t.wrk_days IS NOT NULL AND t.wrk_days > 0 THEN t.wrk_days               WHEN t.no_of_days IS NOT NULL AND t.no_of_days > 0 THEN t.no_of_days               ELSE 1.0             END           ), 0)         INTO v_prj_total_weight, v_prj_completed_weight         FROM milestone_live_master m         JOIN task_live_master t ON t.m_id = m.m_id         LEFT JOIN task_status_master tsm ON tsm.status_id = t.task_sts         WHERE m.prj_id = rec.prj_id;          IF v_prj_total_weight > 0 THEN           v_prj_progress := (v_prj_completed_weight / v_prj_total_weight) * 100.0;         ELSE           v_prj_progress := 0.0;         END IF;       END IF;       v_progress_sum := v_progress_sum + v_prj_progress;     ELSE       v_prj_progress := 0.0;     END IF;      IF rec.prj_sts = 'CLOSED' THEN       v_p_completed := v_p_completed + 1;     ELSIF rec.prj_sts = 'LIVE' AND rec.end_dt IS NOT NULL AND rec.end_dt < v_today AND v_prj_progress < 100 THEN       v_p_delayed := v_p_delayed + 1;       v_delayed_prj := v_delayed_prj + 1;     ELSIF rec.prj_sts = 'LIVE' THEN       v_p_in_progress := v_p_in_progress + 1;     ELSE       v_p_not_started := v_p_not_started + 1;     END IF;      IF rec.prj_sts = 'LIVE' AND rec.end_dt >= v_today AND rec.end_dt < v_today + 7 THEN       v_may_delay_prj := v_may_delay_prj + 1;     END IF;   END LOOP;    v_overall_pct := CASE WHEN v_active_prj > 0 THEN v_progress_sum / v_active_prj ELSE 0 END;    IF v_earliest_start IS NOT NULL AND v_latest_end IS NOT NULL AND v_latest_end > v_earliest_start THEN     v_planned_pct := LEAST(100, GREATEST(0,       ((v_today - v_earliest_start)::NUMERIC / (v_latest_end - v_earliest_start)) * 100));   END IF;    FOR rec IN SELECT mlstn_sts, st_dt, end_dt FROM milestone_live_master LOOP     IF rec.mlstn_sts IN ('COMPLETED','CLOSED') THEN       v_ms_completed := v_ms_completed + 1;     ELSIF rec.end_dt IS NOT NULL AND rec.end_dt < v_today THEN       v_ms_delayed := v_ms_delayed + 1;     ELSIF rec.st_dt IS NOT NULL AND rec.st_dt < v_today THEN       v_ms_in_progress := v_ms_in_progress + 1;     ELSE       v_ms_not_started := v_ms_not_started + 1;     END IF;   END LOOP;    FOR rec IN     SELECT t.task_sts, t.end_dt, tsm.status_nm, t.sub_status     FROM task_live_master t     LEFT JOIN task_status_master tsm ON tsm.status_id = t.task_sts   LOOP     v_t_total := v_t_total + 1;     IF rec.status_nm = 'Completed' THEN       v_t_completed := v_t_completed + 1;     ELSIF rec.sub_status = 'Overdue' OR (rec.status_nm <> 'Completed' AND rec.end_dt IS NOT NULL AND rec.end_dt < v_today) THEN       v_t_overdue := v_t_overdue + 1;     ELSIF rec.status_nm = 'WIP' AND rec.sub_status = 'Under Review' THEN       v_t_under_review := v_t_under_review + 1;     ELSIF rec.status_nm = 'WIP' THEN       v_t_in_progress := v_t_in_progress + 1;     ELSE       v_t_not_started := v_t_not_started + 1;     END IF;   END LOOP;    SELECT COALESCE(jsonb_agg(sub), '[]'::jsonb) INTO v_delayed_ms   FROM (     SELECT jsonb_build_object(       'milestoneTitle',m.mlstn_ttl,'projectCd',p.prj_cd,       'delayDays',(v_today - m.end_dt)) AS sub     FROM milestone_live_master m JOIN project_live_master p ON p.prj_id = m.prj_id     WHERE m.mlstn_sts NOT IN ('COMPLETED','CLOSED')       AND m.end_dt IS NOT NULL AND m.end_dt < v_today     ORDER BY m.end_dt ASC LIMIT 5   ) x;    SELECT COALESCE(jsonb_agg(sub), '[]'::jsonb) INTO v_upcoming_ms   FROM (     SELECT jsonb_build_object(       'milestoneTitle',m.mlstn_ttl,'projectCd',p.prj_cd,       'dueDate',TO_CHAR(m.st_dt,'DD-Mon-YYYY'),'status',COALESCE(m.mlstn_sts,'Pending')) AS sub     FROM milestone_live_master m JOIN project_live_master p ON p.prj_id = m.prj_id     WHERE m.mlstn_sts NOT IN ('COMPLETED','CLOSED')       AND m.st_dt >= v_today AND m.st_dt < v_today + 30     ORDER BY m.st_dt ASC LIMIT 5   ) x;    SELECT COALESCE(jsonb_agg(sub), '[]'::jsonb) INTO v_hp_tasks   FROM (     SELECT jsonb_build_object(       'taskNm',t.task_nm,'projectCd',COALESCE(p.prj_cd,''),       'assigneeNm', COALESCE(          NULLIF(TRIM(COALESCE(e.fst_nm,'')||' '||COALESCE(e.lst_nm,'')), ''),          ext.ext_emp_nm,          ''       ),       'dueDate',TO_CHAR(t.end_dt,'DD-Mon-YYYY')) AS sub     FROM task_live_master t     LEFT JOIN milestone_live_master m ON m.m_id = t.m_id     LEFT JOIN project_live_master p ON p.prj_id = m.prj_id     LEFT JOIN employee_master e ON e.emp_id = t.emp_id     LEFT JOIN external_employee_master ext ON ext.ext_emp_id = t.ext_emp_id     WHERE t.task_sts <> 4 AND t.end_dt >= v_today     ORDER BY t.priority DESC, t.end_dt ASC LIMIT 5   ) x;    RETURN jsonb_build_object(     'summary', jsonb_build_object(       'totalProjects',v_total_prj,'liveProjects',v_live_prj,       'liveProjectsPercentage',CASE WHEN v_total_prj>0 THEN ROUND((v_live_prj::NUMERIC/v_total_prj)*100,2) ELSE 0 END,       'overallProgress',ROUND(v_overall_pct,2),       'delayedProjects',v_delayed_prj,       'delayedProjectsPercentage',CASE WHEN v_total_prj>0 THEN ROUND((v_delayed_prj::NUMERIC/v_total_prj)*100,2) ELSE 0 END,       'overdueTasksCount',v_t_overdue,       'overdueTasksPercentage',CASE WHEN v_t_total>0 THEN ROUND((v_t_overdue::NUMERIC/v_t_total)*100,2) ELSE 0 END,       'upcomingMilestonesCount',jsonb_array_length(v_upcoming_ms)),     'portfolioProgress', jsonb_build_object(       'completed',v_p_completed,'inProgress',v_p_in_progress,       'notStarted',v_p_not_started,'delayed',v_p_delayed,       'total',v_p_completed+v_p_in_progress+v_p_not_started+v_p_delayed),     'milestoneStatus', jsonb_build_object(       'completed',v_ms_completed,'inProgress',v_ms_in_progress,       'notStarted',v_ms_not_started,'delayed',v_ms_delayed,       'total',v_ms_completed+v_ms_in_progress+v_ms_not_started+v_ms_delayed),     'taskStatus', jsonb_build_object(       'completed',v_t_completed,'inProgress',v_t_in_progress,       'underReview',v_t_under_review,'notStarted',v_t_not_started,       'overdue',v_t_overdue,       'total',v_t_total),     'forecastSummary', jsonb_build_object(       'currentProgress',ROUND(v_overall_pct,2),       'plannedProgress',ROUND(v_planned_pct,2),       'variance',ROUND(v_overall_pct-v_planned_pct,2),       'expectedCompletionDate',TO_CHAR(v_latest_end,'DD-Mon-YYYY'),       'daysAhead',CASE WHEN v_latest_end IS NOT NULL THEN (v_latest_end-v_today) ELSE 0 END,       'projectsAtRiskCount',v_delayed_prj,       'projectsAtRiskPercentage',CASE WHEN v_total_prj>0 THEN ROUND((v_delayed_prj::NUMERIC/v_total_prj)*100,2) ELSE 0 END,       'onTrackProjectsCount',v_total_prj-v_delayed_prj,       'onTrackProjectsPercentage',CASE WHEN v_total_prj>0 THEN ROUND(((v_total_prj-v_delayed_prj)::NUMERIC/v_total_prj)*100,2) ELSE 0 END,       'mayDelayProjectsCount',v_may_delay_prj,       'mayDelayProjectsPercentage',CASE WHEN v_total_prj>0 THEN ROUND((v_may_delay_prj::NUMERIC/v_total_prj)*100,2) ELSE 0 END,       'atRiskProjectsCount',v_delayed_prj,       'atRiskProjectsPercentage',CASE WHEN v_total_prj>0 THEN ROUND((v_delayed_prj::NUMERIC/v_total_prj)*100,2) ELSE 0 END),     'delayedMilestones', v_delayed_ms,     'upcomingMilestones',v_upcoming_ms,     'highPriorityTasks', v_hp_tasks   ); END; 